/**
 * gen-config-docs.ts — Generates the Starlight configuration reference from
 * schemas/config.schema.json (the schema of .wombo-combo/config.json).
 *
 * Output (deterministic) goes to docs/src/content/docs/reference/config.md.
 *
 * Usage: bun scripts/gen-config-docs.ts   (or: bun run docs:gen)
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const GENERATED_BANNER =
  "<!-- GENERATED by scripts/gen-config-docs.ts from schemas/config.schema.json. Do not edit by hand. -->";

interface SchemaNode {
  type?: string | string[];
  description?: string;
  default?: unknown;
  enum?: unknown[];
  minimum?: number;
  items?: SchemaNode;
  properties?: Record<string, SchemaNode>;
  title?: string;
  [key: string]: unknown;
}

export interface ConfigRow {
  /** Dotted path, e.g. "build.command" */
  key: string;
  node: SchemaNode;
}

function escapeCell(text: string): string {
  return text.replace(/\r?\n+/g, " ").replace(/\|/g, "\\|").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function code(value: string): string {
  return `\`${value}\``;
}

export function formatType(node: SchemaNode): string {
  const t = node.type;
  if (Array.isArray(t)) return t.join(" \\| ");
  if (t === "array") return `${node.items ? formatType(node.items) : "any"}[]`;
  return t ?? "any";
}

/** Depth-first flatten of leaf properties, in schema order. */
export function flattenSchema(schema: SchemaNode, prefix = ""): ConfigRow[] {
  const rows: ConfigRow[] = [];
  for (const [name, node] of Object.entries(schema.properties ?? {})) {
    const key = prefix ? `${prefix}.${name}` : name;
    if (node.properties) rows.push(...flattenSchema(node, key));
    else rows.push({ key, node });
  }
  return rows;
}

function row(r: ConfigRow): string {
  const { node } = r;
  const notes: string[] = [];
  if (node.enum) notes.push(`Values: ${node.enum.map((v) => code(String(v))).join(", ")}.`);
  if (node.minimum !== undefined) notes.push(`Minimum: ${code(String(node.minimum))}.`);
  const desc = [escapeCell(node.description ?? ""), ...notes].filter(Boolean).join(" ");
  const def = node.default === undefined ? "" : code(JSON.stringify(node.default).replace(/\|/g, "\\|"));
  return `| ${code(r.key)} | ${formatType(node)} | ${def} | ${desc} |`;
}

export function renderConfigPage(schema: SchemaNode): string {
  const rows = flattenSchema(schema);
  const groups = new Map<string, ConfigRow[]>();
  for (const r of rows) {
    const group = r.key.includes(".") ? r.key.split(".")[0] : "";
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group)!.push(r);
  }

  const lines: string[] = [
    "---",
    "title: Configuration reference",
    'description: "Every option of .wombo-combo/config.json, generated from the JSON schema."',
    "---",
    "",
    GENERATED_BANNER,
    "",
    "Project configuration lives in `.wombo-combo/config.json`. Every option is optional; omitted options use",
    "the defaults below. The `$schema` key is accepted for editor validation.",
    "",
  ];
  const ordered = [...groups.keys()].filter((g) => g === "").concat([...groups.keys()].filter((g) => g !== ""));
  for (const group of ordered) {
    lines.push(group === "" ? "## Top-level options" : `## ${code(group)}`, "");
    const own = schema.properties?.[group];
    if (group !== "" && own?.description) lines.push(escapeCell(own.description), "");
    lines.push("| Option | Type | Default | Description |", "| --- | --- | --- | --- |");
    for (const r of groups.get(group)!) lines.push(row(r));
    lines.push("");
  }
  return lines.join("\n");
}

if (import.meta.main) {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
  const schema = JSON.parse(readFileSync(join(root, "schemas/config.schema.json"), "utf-8"));
  const outFile = join(root, "docs/src/content/docs/reference/config.md");
  mkdirSync(dirname(outFile), { recursive: true });
  const content = renderConfigPage(schema);
  writeFileSync(outFile, content);
  console.log(`Wrote config reference (${flattenSchema(schema).length} options) to ${outFile}`);
}
